import re
from typing import Annotated

from fastapi import Depends, Header, HTTPException, Request

from app.core.config import get_settings
from app.db.session import SessionDep
from app.features.profiles.repository import get_or_create_user
from app.features.profiles.service import ProfileService
from app.features.trips.service import TripService

USER_ID = re.compile(r"^[A-Za-z0-9_-]{3,64}$")


async def current_user_id(request: Request, session: SessionDep, x_user_id: Annotated[str | None, Header()] = None) -> str:
    """MVP identity: an anonymous id generated by the client. Swap for real auth later."""
    user_id = x_user_id or get_settings().default_user_id
    if not USER_ID.match(user_id):
        raise HTTPException(400, "Invalid X-User-Id")
    await get_or_create_user(session, user_id, getattr(request.app.state, "seed_new_user", None))
    return user_id


UserIdDep = Annotated[str, Depends(current_user_id)]


def get_profile_service(session: SessionDep) -> ProfileService:
    return ProfileService(session, TripService(session))


ProfileServiceDep = Annotated[ProfileService, Depends(get_profile_service)]
